-- v41 (A1 multi-associazione) — Configurazione dell'associazione in public.app_settings, chiave 'brand'.
-- Additiva: nessuna tabella/colonna rimossa; la v40.6 continua a funzionare (ignora la nuova riga).
-- Lettura: authenticated (policy esistente app_settings_read). anon: nessun GRANT (la schermata di accesso usa la copia locale o i valori PerGioco).
-- Scrittura: solo admin (policy esistente app_settings_admin_write = is_admin()), più validazione lato server con vincolo CHECK.

create or replace function public.brand_valid(v jsonb) returns boolean
language plpgsql immutable set search_path = public as $$
declare k text; s text; c jsonb; raw text;
begin
  if v is null or jsonb_typeof(v)<>'object' then return false; end if;
  for k in select jsonb_object_keys(v) loop
    if k not in ('nome','motto','citta','instagram','email','logo','logo_barra','colori') then return false; end if;
  end loop;
  if coalesce(length(btrim(v->>'nome')),0) not between 2 and 40 then return false; end if;
  if length(coalesce(v->>'motto',''))>80 or length(coalesce(v->>'citta',''))>40 then return false; end if;
  if coalesce(v->>'instagram','')<>'' and (v->>'instagram') !~ '^[A-Za-z0-9._]{1,30}$' then return false; end if;
  if coalesce(v->>'email','')<>'' and ((v->>'email') !~ '^[^@\s<>"]+@[^@\s<>"]+\.[A-Za-z]{2,}$' or length(v->>'email')>120) then return false; end if;
  foreach k in array array['logo','logo_barra'] loop
    s:=coalesce(v->>k,'');
    if s='' then continue; end if;
    if length(s)>150000 then return false; end if;
    if s ~ '^https://[^\s"<>]+$' then continue; end if;
    if s !~ '^data:image/(svg\+xml|png|jpeg|webp);base64,[A-Za-z0-9+/=]+$' then return false; end if;
    if s ~ '^data:image/svg' then
      begin raw:=convert_from(decode(substr(s,strpos(s,',')+1),'base64'),'UTF8');
      exception when others then return false; end;
      if raw ~* '(<script|javascript:|\son[a-z]+\s*=|<foreignObject|xlink:href\s*=\s*["'']?\s*(https?|data):)' then return false; end if;
    end if;
  end loop;
  c:=v->'colori';
  if c is not null then
    if jsonb_typeof(c)<>'object' then return false; end if;
    for k in select jsonb_object_keys(c) loop
      if k not in ('primario','secondario','accento','sfondo') then return false; end if;
      if (c->>k) !~ '^#[0-9A-Fa-f]{6}$' then return false; end if;
    end loop;
  end if;
  return true;
end $$;
revoke all on function public.brand_valid(jsonb) from public, anon;
grant execute on function public.brand_valid(jsonb) to authenticated;

alter table public.app_settings drop constraint if exists app_settings_brand_chk;
alter table public.app_settings add constraint app_settings_brand_chk check (key<>'brand' or public.brand_valid(value));

-- nessun accesso anonimo (ribadito)
revoke all on public.app_settings from anon;

insert into public.app_settings(key,value) values ('brand', jsonb_build_object(
  'nome','PerGioco','motto','Gioca, prenota, condividi','citta','Ragusa','instagram','pergiocoets','email','',
  'logo_barra','data:image/svg+xml;base64,',
  'logo','data:image/svg+xml;base64,',
  'colori',jsonb_build_object('primario','#14254a','secondario','#2a4785','accento','#f2b134','sfondo','#f4f6fb')))
on conflict (key) do nothing;
